  final String? description;
  final String assetAccountId;
  final String accumulatedDepreciationAccountId;
  final String depreciationExpenseAccountId;
  final int acquisitionCost;
  final int salvageValue;
  final DateTime acquisitionDate;
  final DateTime? disposalDate;
  final int usefulLifeMonths;
  final int? usefulLifeUnits;
  final String depreciationMethod;
  final double? decliningBalanceRate;
  final int totalDepreciation;
  final int currentPeriodDepreciation;
  final int unitsUsed;
  final String status;
  const FixedAsset({
    required this.id,
    required this.createdAt,
    required this.lastUpdated,
    this.tenantId,
    required this.isDeleted,
    required this.name,
    this.description,
    required this.assetAccountId,
    required this.accumulatedDepreciationAccountId,
    required this.depreciationExpenseAccountId,
    required this.acquisitionCost,
    required this.salvageValue,
    required this.acquisitionDate,
    this.disposalDate,
    required this.usefulLifeMonths,
    this.usefulLifeUnits,
    required this.depreciationMethod,
    this.decliningBalanceRate,
    required this.totalDepreciation,
    required this.currentPeriodDepreciation,
    required this.unitsUsed,
    required this.status,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['last_updated'] = Variable<DateTime>(lastUpdated);
    if (!nullToAbsent || tenantId != null) {
      map['tenant_id'] = Variable<String>(tenantId);
    }
    map['is_deleted'] = Variable<bool>(isDeleted);
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || description != null) {
      map['description'] = Variable<String>(description);
    }
    map['asset_account_id'] = Variable<String>(assetAccountId);
    map['accumulated_depreciation_account_id'] = Variable<String>(
      accumulatedDepreciationAccountId,
    );
    map['depreciation_expense_account_id'] = Variable<String>(
      depreciationExpenseAccountId,
    );
    map['acquisition_cost'] = Variable<int>(acquisitionCost);
    map['salvage_value'] = Variable<int>(salvageValue);
    map['acquisition_date'] = Variable<DateTime>(acquisitionDate);
    if (!nullToAbsent || disposalDate != null) {
      map['disposal_date'] = Variable<DateTime>(disposalDate);
    }
    map['useful_life_months'] = Variable<int>(usefulLifeMonths);
    if (!nullToAbsent || usefulLifeUnits != null) {
      map['useful_life_units'] = Variable<int>(usefulLifeUnits);
    }
    map['depreciation_method'] = Variable<String>(depreciationMethod);
    if (!nullToAbsent || decliningBalanceRate != null) {
