    return FixedAssetsCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      lastUpdated: Value(lastUpdated),
      tenantId: tenantId == null && nullToAbsent
          ? const Value.absent()
          : Value(tenantId),
      isDeleted: Value(isDeleted),
      name: Value(name),
      description: description == null && nullToAbsent
          ? const Value.absent()
          : Value(description),
